CREATE DATABASE IF NOT EXISTS inventory_db CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE inventory_db;
CREATE TABLE warehouses (id BINARY(16) NOT NULL, code VARCHAR(40) NOT NULL, name VARCHAR(160) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, PRIMARY KEY(id), UNIQUE KEY uk_warehouse_code(code)) ENGINE=InnoDB;
CREATE TABLE stock_items (id BINARY(16) NOT NULL, variant_id BINARY(16) NOT NULL, warehouse_id BINARY(16) NOT NULL, available_quantity INT NOT NULL DEFAULT 0, reserved_quantity INT NOT NULL DEFAULT 0, reorder_level INT NOT NULL DEFAULT 0, version BIGINT NOT NULL DEFAULT 0, updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_stock_variant_warehouse(variant_id,warehouse_id), KEY ix_stock_variant(variant_id), CONSTRAINT ck_stock_quantities CHECK(available_quantity >= 0 AND reserved_quantity >= 0), CONSTRAINT fk_stock_warehouse FOREIGN KEY(warehouse_id) REFERENCES warehouses(id)) ENGINE=InnoDB;
CREATE TABLE inventory_reservations (id BINARY(16) NOT NULL, order_id BINARY(16) NOT NULL, variant_id BINARY(16) NOT NULL, warehouse_id BINARY(16) NOT NULL, quantity INT NOT NULL, status ENUM('RESERVED','CONFIRMED','RELEASED','EXPIRED') NOT NULL, expires_at TIMESTAMP(6) NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_reservation_order_variant(order_id,variant_id), KEY ix_reservation_expiry(status,expires_at), CONSTRAINT ck_reservation_quantity CHECK(quantity > 0), CONSTRAINT fk_reservation_warehouse FOREIGN KEY(warehouse_id) REFERENCES warehouses(id)) ENGINE=InnoDB;
CREATE TABLE outbox_event (id BINARY(16) NOT NULL, aggregate_type VARCHAR(80) NOT NULL, aggregate_id BINARY(16) NOT NULL, event_type VARCHAR(120) NOT NULL, payload JSON NOT NULL, occurred_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), published_at TIMESTAMP(6), attempts INT NOT NULL DEFAULT 0, PRIMARY KEY(id), KEY ix_outbox_unpublished(published_at,occurred_at)) ENGINE=InnoDB;
